import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import {
  deleteShippingOrder,
  listShippingOrders,
  type ShippingOrderFilterQuery,
  type ShippingOrderListItem,
} from '../../../services/shippingOrders/endpoint';
import { useAppDispatch } from '../../../store/hooks';
import df from '../../../styles/documentForm.module.css';

type SearchState = {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  dienGiai: string;
  maKho: string;
  maVt: string;
  maPost: string;
  maGd: string;
  maQuyen: string;
  tkNo: string;
  tkCo: string;
  nhVt1: string;
  nhVt2: string;
  nhVt3: string;
  nhVt4: string;
  nhVt5: string;
  tien1: string;
  tien2: string;
  maPhi: string;
  maVv: string;
  maHd: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
};

const EMPTY_SEARCH: SearchState = {
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  dienGiai: '',
  maKho: '',
  maVt: '',
  maPost: '9',
  maGd: '',
  maQuyen: '',
  tkNo: '',
  tkCo: '',
  nhVt1: '',
  nhVt2: '',
  nhVt3: '',
  nhVt4: '',
  nhVt5: '',
  tien1: '',
  tien2: '',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
};

const NH_VT = ['nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5'] as const;
const MA_TD = ['maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5'] as const;
const EXTRA_CODES: { key: keyof SearchState; label: string }[] = [
  { key: 'maPhi', label: 'Khoản mục' },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'maKu', label: 'Khế ước' },
  { key: 'maTtln', label: 'Trung tâm lợi nhuận' },
  { key: 'maTtcp', label: 'Trung tâm chi phí' },
  { key: 'maBp', label: 'Phòng ban' },
  { key: 'maHs', label: 'Nhân sự' },
  { key: 'maCd', label: 'Công đoạn' },
];
const POST_VALUES = ['3', '5', '7', '9'] as const;

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function toQuery(state: SearchState): ShippingOrderFilterQuery {
  const maPost = POST_VALUES.includes(state.maPost as (typeof POST_VALUES)[number]) ? state.maPost : '9';
  const query: ShippingOrderFilterQuery = { maPost };
  const textKeys: (keyof SearchState)[] = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maKh', 'dienGiai', 'maKho', 'maVt',
    'maQuyen', 'tkNo', 'tkCo', 'nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5',
    'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp', 'maBp', 'maHs', 'maCd',
    'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = state[key];
    if (typeof value === 'string' && value.trim()) {
      (query as Record<string, string>)[key] = value.trim();
    }
  });
  if (state.maGd === '4') query.maGd = '4';
  const tien1 = Number(state.tien1);
  const tien2 = Number(state.tien2);
  if (state.tien1.trim() !== '' && Number.isFinite(tien1) && tien1 !== 0) query.tien1 = tien1;
  if (state.tien2.trim() !== '' && Number.isFinite(tien2) && tien2 !== 0) query.tien2 = tien2;
  if (state.locNsd) query.locNsd = true;
  return query;
}

const HdlListPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [search, setSearch] = useState<SearchState>(EMPTY_SEARCH);
  const [items, setItems] = useState<ShippingOrderListItem[]>([]);
  const [filtering, setFiltering] = useState(false);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const patch = (next: Partial<SearchState>) => setSearch(prev => ({ ...prev, ...next }));

  const applyRows = (rows: ShippingOrderListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadTop = async () => {
    setError('');
    setLoading(true);
    try {
      applyRows(await listShippingOrders({ loadTop: 5 }));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách lệnh xuất hàng');
    } finally {
      setLoading(false);
    }
  };

  const runSearch = async (state: SearchState) => {
    setFiltering(true);
    setError('');
    setLoading(true);
    try {
      applyRows(await listShippingOrders(toQuery(state)));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách lệnh xuất hàng');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadTop();
  }, []);

  const onSearch = () => {
    void runSearch(search);
  };

  const onRefresh = () => {
    if (!filtering) {
      void loadTop();
      return;
    }
    void runSearch(search);
  };

  const onDelete = async () => {
    if (!selectedSttRec || deleting) return;
    setDeleting(true);
    setError('');
    try {
      await deleteShippingOrder(selectedSttRec);
      dispatchAppToast(dispatch, { message: 'Đã xóa lệnh xuất hàng', type: 'success' });
      setSelectedSttRec('');
      if (filtering) await runSearch(search);
      else await loadTop();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Xóa thất bại');
    } finally {
      setDeleting(false);
    }
  };

  const onEnter = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;
  const emptyText = filtering ? 'Không tìm thấy lệnh xuất hàng' : 'Không có lệnh xuất hàng';

  return (
    <div className={df.page} data-testid="ct-hdl-list">
      <h1 data-testid="ct-hdl-title">Lệnh xuất hàng</h1>
      <div>
        <Button variant="secondary" data-testid="ct-hdl-toolbar-refresh-btn" onClick={onRefresh} loading={loading}>
          Làm mới
        </Button>
        <Button variant="primary" data-testid="ct-hdl-toolbar-add-btn" onClick={() => navigate('/bh/hdl/them')}>
          Thêm
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hdl-toolbar-edit-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hdl/${encodeURIComponent(selectedSttRec)}`)}
        >
          Sửa
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hdl-toolbar-view-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hdl/${encodeURIComponent(selectedSttRec)}?mode=view`)}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-hdl-toolbar-copy-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/hdl/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}
        >
          Sao chép
        </Button>
        <Button
          variant="danger"
          data-testid="ct-hdl-toolbar-delete-btn"
          disabled={noSelection || deleting}
          loading={deleting}
          onClick={() => { void onDelete(); }}
        >
          Xóa
        </Button>
      </div>

      <section className={df.section} data-testid="ct-hdl-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Ngày từ</label>
            <Input type="date" data-testid="ct-hdl-search-ngayCt1" value={search.ngayCt1} onKeyDown={onEnter} onChange={e => patch({ ngayCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Ngày đến</label>
            <Input type="date" data-testid="ct-hdl-search-ngayCt2" value={search.ngayCt2} onKeyDown={onEnter} onChange={e => patch({ ngayCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số lệnh từ</label>
            <Input data-testid="ct-hdl-search-soCt1" value={search.soCt1} onKeyDown={onEnter} onChange={e => patch({ soCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số lệnh đến</label>
            <Input data-testid="ct-hdl-search-soCt2" value={search.soCt2} onKeyDown={onEnter} onChange={e => patch({ soCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Khách hàng</label>
            <Input data-testid="ct-hdl-search-maKh" value={search.maKh} onKeyDown={onEnter} onChange={e => patch({ maKh: e.target.value })} />
          </div>
          <div className={`${df.field} ${df.spanCol2}`}>
            <label className={df.label}>Diễn giải</label>
            <Input data-testid="ct-hdl-search-dienGiai" value={search.dienGiai} onKeyDown={onEnter} onChange={e => patch({ dienGiai: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Kho</label>
            <Input data-testid="ct-hdl-search-maKho" value={search.maKho} onKeyDown={onEnter} onChange={e => patch({ maKho: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Hàng hoá</label>
            <Input data-testid="ct-hdl-search-maVt" value={search.maVt} onKeyDown={onEnter} onChange={e => patch({ maVt: e.target.value })} />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-hdl-search-btn" onClick={onSearch} loading={loading}>
          Tìm
        </Button>
      </section>

      <section className={df.section} data-testid="ct-hdl-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Trạng thái</label>
            <Select
              data-testid="ct-hdl-search-maPost"
              value={search.maPost}
              onChange={e => patch({ maPost: e.target.value })}
              options={[
                { value: '3', label: 'Lập lệnh xuất hàng' },
                { value: '5', label: 'Lệnh xuất hàng đã duyệt' },
                { value: '7', label: 'Lệnh đang xuất hàng' },
                { value: '9', label: 'Đóng lệnh' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại giao dịch</label>
            <Select
              data-testid="ct-hdl-search-maGd"
              value={search.maGd}
              onChange={e => patch({ maGd: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '4', label: 'Lệnh xuất hàng' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Quyền số</label>
            <Input data-testid="ct-hdl-search-maQuyen" value={search.maQuyen} onKeyDown={onEnter} onChange={e => patch({ maQuyen: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK nợ</label>
            <Input data-testid="ct-hdl-search-tkNo" value={search.tkNo} onKeyDown={onEnter} onChange={e => patch({ tkNo: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK có</label>
            <Input data-testid="ct-hdl-search-tkCo" value={search.tkCo} onKeyDown={onEnter} onChange={e => patch({ tkCo: e.target.value })} />
          </div>
          {NH_VT.map((key, index) => (
            <div className={df.field} key={key}>
              <label className={df.label}>{`Nhóm hàng ${index + 1}`}</label>
              <Input
                data-testid={`ct-hdl-search-${key}`}
                value={search[key]}
                onKeyDown={onEnter}
                onChange={e => patch({ [key]: e.target.value })}
              />
            </div>
          ))}
          <div className={df.field}>
            <label className={df.label}>Tiền từ</label>
            <Input inputMode="decimal" data-testid="ct-hdl-search-tien1" value={search.tien1} onKeyDown={onEnter} onChange={e => patch({ tien1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Tiền đến</label>
            <Input inputMode="decimal" data-testid="ct-hdl-search-tien2" value={search.tien2} onKeyDown={onEnter} onChange={e => patch({ tien2: e.target.value })} />
          </div>
          {EXTRA_CODES.map(field => (
            <div className={df.field} key={field.key}>
              <label className={df.label}>{field.label}</label>
              <Input
                data-testid={`ct-hdl-search-${field.key}`}
                value={search[field.key] as string}
                onKeyDown={onEnter}
                onChange={e => patch({ [field.key]: e.target.value })}
              />
            </div>
          ))}
          {MA_TD.map((key, index) => (
            <div className={df.field} key={key}>
              <label className={df.label}>{`Mã tự do ${index + 1}`}</label>
              <Input
                data-testid={`ct-hdl-search-${key}`}
                value={search[key]}
                onKeyDown={onEnter}
                onChange={e => patch({ [key]: e.target.value })}
              />
            </div>
          ))}
          <div className={df.field}>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-hdl-search-locNsd"
              checked={search.locNsd}
              onChange={e => patch({ locNsd: e.target.checked })}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-hdl-grid">
          <thead>
            <tr>
              <th>Số lệnh</th>
              <th>Ngày</th>
              <th>Khách hàng</th>
              <th>Khách hàng</th>
              <th>Tiền hàng</th>
              <th>Tiền thuế</th>
              <th>Tổng cộng</th>
              <th>Ngoại tệ</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => {
              const selected = row.sttRec === selectedSttRec;
              return (
                <tr
                  key={row.sttRec}
                  aria-selected={selected}
                  onClick={() => setSelectedSttRec(row.sttRec)}
                  style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                >
                  <td>{row.soCt}</td>
                  <td>{showDate(row.ngayCt)}</td>
                  <td>{row.maKh}</td>
                  <td>{row.tenKh}</td>
                  <td>{showMoney(row.tTienNt2 ?? 0)}</td>
                  <td>{showMoney(row.tThueNt ?? 0)}</td>
                  <td>{showMoney(row.tTienNt3 ?? 0)}</td>
                  <td>{row.maNt}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {items.length === 0 ? <div>{emptyText}</div> : null}
    </div>
  );
};

export default HdlListPage;
